mapper.select:
SELECT count(*) FROM (
	SELECT 1
	FROM posts p
	WHERE p.user_id <> #{viewerId}

		AND 


		AND (p.created_at, p.id) > (SELECT a.created_at, a.id FROM posts a WHERE a.id = #{afterId})

	LIMIT #{max}
) AS newer

mapper.update:
UPDATE posts
SET content = #{content}, edited_at = now(), updated_at = now()
WHERE id = #{id} AND user_id = #{userId}
